package org.sleepwell.app;
import java.time.*;import java.util.*;import org.json.*;
/** One recurring source occurrence replaced by one explicit current-zone local clock time. */
final class NextAlarmOverride {
 final String nonce,baseKey,reviewZone;final LocalDate sourceDate,targetDate;final int hour,minute;final long last;
 NextAlarmOverride(String nonce,String baseKey,LocalDate sourceDate,LocalDate targetDate,int hour,int minute,long last,String reviewZone){if(!BackupRuntime.nonce(nonce)||baseKey==null||!baseKey.matches("[0-9a-f]{64}")||sourceDate==null||targetDate==null||sourceDate.getYear()<1970||sourceDate.getYear()>9998||targetDate.getYear()<1970||targetDate.getYear()>9998||hour<0||hour>23||minute<0||minute>59||last<0||reviewZone==null||reviewZone.length()>100)throw new IllegalArgumentException("Invalid next-alarm override.");ZoneId.of(reviewZone);this.nonce=nonce;this.baseKey=baseKey;this.sourceDate=sourceDate;this.targetDate=targetDate;this.hour=hour;this.minute=minute;this.last=last;this.reviewZone=reviewZone;}
 static String baseKey(Alarm alarm){try{JSONObject row=new JSONObject().put("id",alarm.id).put("hour",alarm.hour).put("minute",alarm.minute).put("days",new JSONArray(new TreeSet<>(alarm.days))).put("repeat",AlarmRepeat.encode(alarm.repeatRule)).put("excluded",AlarmExcludedDates.encode(alarm.excludedDates));if(alarm.solar!=null)row.put("solar",SunriseScheduleJson.encode(alarm.solar));byte[] bytes=java.security.MessageDigest.getInstance("SHA-256").digest(row.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));StringBuilder result=new StringBuilder();for(byte value:bytes)result.append(String.format(Locale.ROOT,"%02x",value&255));return result.toString();}catch(java.security.NoSuchAlgorithmException|JSONException impossible){throw new IllegalStateException(impossible);}}
 void shape(Alarm alarm){if(alarm.id<=0||alarm.days.isEmpty()||alarm.nap!=null||alarm.napInvalid||alarm.date!=null||alarm.dateInvalid||alarm.repeatInvalid||!alarm.repeatRule.validFor(alarm)||alarm.solarInvalid||alarm.excludedDatesInvalid||alarm.skipInvalid||!baseKey.equals(baseKey(alarm))||!alarm.repeatRule.accepts(sourceDate)||!alarm.days.contains(sourceDate.getDayOfWeek().getValue())||alarm.excludedDates.contains(sourceDate)||alarm.excludedDates.contains(targetDate))throw new IllegalArgumentException("The saved base schedule changed. Undo the next-alarm override before editing its recurrence.");if(alarm.skip!=null&&!alarm.skip.date.equals(sourceDate))throw new IllegalArgumentException("This skip does not belong to the overridden source occurrence.");}
 long sourceAt(Alarm alarm,ZoneId zone){return alarm.solar==null?AlarmDate.at(sourceDate,alarm.hour,alarm.minute,zone):alarm.solar.on(sourceDate,alarm.hour,alarm.minute,zone).at;}
 long at(ZoneId zone){LocalDateTime local=targetDate.atTime(hour,minute);List<ZoneOffset> offsets=zone.getRules().getValidOffsets(local);if(offsets.size()!=1)throw new IllegalArgumentException("The selected next-alarm time is missing or repeats in this time zone. Review an unambiguous time.");return local.toInstant(offsets.get(0)).toEpochMilli();}
 void portable(Alarm alarm){check(alarm,ZoneId.of(reviewZone),false);}
 void check(Alarm alarm,ZoneId zone){check(alarm,zone,true);}
 private void check(Alarm alarm,ZoneId zone,boolean validateSkip){shape(alarm);long source=sourceAt(alarm,zone),target=at(zone),following=alarm.nextOrdinary(source,zone);if(source<=last||!alarm.occursOrdinary(source,zone)||following<=source||target>=following)throw new IllegalArgumentException("The override must be before the following ordinary occurrence. Review its source and target.");if(validateSkip&&alarm.skip!=null&&!alarm.skip.excludes(source,zone))throw new IllegalArgumentException("This skipped source changed in the current time zone. Undo the override and review it again.");}
 boolean skipped(Alarm alarm,ZoneId zone){return alarm.skip!=null&&alarm.skip.excludes(sourceAt(alarm,zone),zone);}
 boolean target(long deadline,ZoneId zone){try{return deadline==at(zone);}catch(IllegalArgumentException invalid){return false;}}
 long next(Alarm alarm,long now,ZoneId zone){try{check(alarm,zone);long target=at(zone),source=sourceAt(alarm,zone);if(!skipped(alarm,zone)&&target>now)return target;return alarm.nextOrdinary(Math.max(now,Math.max(source,target)),zone);}catch(RuntimeException invalid){return 0;}}
 boolean occurs(Alarm alarm,long deadline,ZoneId zone){try{check(alarm,zone);long target=at(zone);return deadline==target?!skipped(alarm,zone):deadline>Math.max(target,sourceAt(alarm,zone))&&alarm.occursOrdinary(deadline,zone);}catch(RuntimeException invalid){return false;}}
 String key(){return nonce+":"+baseKey+":"+sourceDate+":"+targetDate+":"+hour+":"+minute+":"+last+":"+reviewZone;}
 static String key(Alarm alarm){return alarm.nextOverrideInvalid?":invalid-next:"+alarm.json().opt("nextOverride"):alarm.nextOverride==null?"":":next:"+alarm.nextOverride.key();}
 static JSONObject encode(NextAlarmOverride value)throws JSONException{return new JSONObject().put("version",1).put("nonce",value.nonce).put("baseKey",value.baseKey).put("sourceDate",value.sourceDate.toString()).put("targetDate",value.targetDate.toString()).put("hour",value.hour).put("minute",value.minute).put("last",value.last).put("reviewZone",value.reviewZone);}
 static NextAlarmOverride decode(Object raw)throws JSONException{if(!(raw instanceof JSONObject row)||row.length()!=9||SensorProvenance.whole(row,"version")!=1)throw new JSONException("Invalid next-alarm override fields");try{return new NextAlarmOverride(SensorProvenance.text(row,"nonce"),SensorProvenance.text(row,"baseKey"),AlarmDate.read(row.get("sourceDate")),AlarmDate.read(row.get("targetDate")),Math.toIntExact(SensorProvenance.whole(row,"hour")),Math.toIntExact(SensorProvenance.whole(row,"minute")),SensorProvenance.whole(row,"last"),SensorProvenance.text(row,"reviewZone"));}catch(RuntimeException invalid){throw new JSONException("Invalid next-alarm override");}}
}
